func (self class) Virtual(name string) reflect.Value {
	switch name {
	default: return gd.VirtualByName(PanelContainer.Advanced(self.AsPanelContainer()), name)
	}
}

func (self Instance) Virtual(name string) reflect.Value {
	switch name {
	default: return gd.VirtualByName(PanelContainer.Instance(self.AsPanelContainer()), name)
	}
}
func init() {gdclass.Register("ScriptEditor", func(ptr gdreference.Object) any { return Instance{gdclass.NewScriptEditor(ptr)} })}
